// ===========================================================================
// Фикстура §6.4: односторонние платформы и повторное включение коллизии.
//
// Две односторонние платформы друг под другом. Актёр стоит на верхней,
// .dropThrough() проваливает его сквозь неё, он приземляется на нижнюю; затем
// тест запускает его снизу вверх сквозь верхнюю — и тот обязан снова на ней
// встать: это и есть проверка, что коллизия включилась обратно.
//
// Запуск:
//   python3 tests/agent/highlevel_physics_oneway_test.py
// ===========================================================================

$.ready(() => {
    $.world.gravity(0, 1800).color('#101820')
        .bounds(0, -400, 2000, 2000, { solid: false });

    // Верхняя платформа: x 800..1200, верх y = 390.
    $('<wall>', { id: 'upper' }).at(1000, 400).size(400, 20).appendTo($.world);
    $('#upper').oneWay(true);

    // Нижняя: та же ширина, верх y = 630. Расстояние 240 px — провал занимает
    // около 30 кадров, и «пролетел мимо» видно сразу.
    $('<wall>', { id: 'lower' }).at(1000, 640).size(400, 20).appendTo($.world);
    $('#lower').oneWay(true);

    // Боковые ограничители: на платформе есть куда идти, но уйти с неё нельзя.
    $('<wall>', { id: 'stop-left' }).at(770, 300).size(20, 220).appendTo($.world);
    $('<wall>', { id: 'stop-right' }).at(1230, 300).size(20, 220).appendTo($.world);

    // Актёр стартует на верхней платформе (её верх 390, полувысота тела 15).
    $('<player>', { id: 'dropper' }).at(1000, 370).size(26, 30)
        .health(100).controls('both').collision(26, 30).appendTo($.world);

    // Тест читает отсюда, что провал вообще случился.
    $.store.set('throughUpper', false);
});

// Отмечаем кадр, в котором тело оказалось ниже верхней платформы.
$.update(() => {
    if ($.store.get('throughUpper')) return;
    if ($('#dropper').pos().y > 420) $.store.set('throughUpper', true);
});
